    'doc.builtin.rapport.body': '# {{datamangd}}\n\n*Report created {{datum}} with {{app}}.*\n\n{{#beskrivning}}{{beskrivning}}\n\n{{/beskrivning}}The dataset contains **{{antal_rader}} rows** and **{{antal_kolumner}} columns**.{{#kalla}} Source: {{kalla}}.{{/kalla}}\n\n## Columns\n\n{{#tabell}}kalla: kolumner; rubrik: Columns in the dataset{{/tabell}}\n\n## The first rows\n\n{{#tabell}}topp: 20; rubrik: The first 20 rows{{/tabell}}\n\n## Charts\n\nInsert a saved chart with the tag diagram followed by the chart name in quotes, see the help on the right. Remove this paragraph when you are done.\n',
    'doc.builtin.kodbok.body': '# Codebook: {{datamangd}}\n\n*Created {{datum}} with {{app}}.*\n\n{{#beskrivning}}{{beskrivning}}\n\n{{/beskrivning}}The dataset has **{{antal_rader}} rows**, **{{antal_kolumner}} columns** and {{dubbletter}} duplicate rows.{{#kalla}} Source: {{kalla}}.{{/kalla}}\n\n{{#kolumner}}\n## {{namn}}\n\n- Type: {{typ}}\n- Label: {{etikett}}\n{{#beskrivning}}- Description: {{beskrivning}}\n{{/beskrivning}}{{#enhet}}- Unit: {{enhet}}\n{{/enhet}}{{#vardeetiketter}}- Value labels: {{vardeetiketter}}\n{{/vardeetiketter}}- Missing values: {{saknade}}\n- Distinct values: {{unika}}{{#ar_unik}} (unique key){{/ar_unik}}\n- Range: {{minsta}} – {{storsta}}\n{{#medel}}- Mean: {{medel}}\n{{/medel}}{{#anmarkningar}}- Remarks: {{anmarkningar}}\n{{/anmarkningar}}\n{{/kolumner}}\n',
    'doc.builtin.grupp.body': '# {{datamangd}}: {{grupp}}\n\n*{{gruppkolumn}} = {{grupp}}. Created {{datum}} with {{app}}.*\n\nThe selection covers **{{antal_rader}} rows**.\n\n{{#tabell}}topp: 50; rubrik: Rows for {{grupp}}{{/tabell}}\n',
