    'course.process.column': 'thousands',
    'course.viz.chart': 'Population per county 2024',
    'course.welcome.title': 'Welcome to Dataspatium',
    'course.welcome.p1': 'Dataspatium imports, processes, analyses, visualises and exports data entirely in the browser. Nothing is installed, and your data stay on your computer unless you fetch from an API yourself.',
    'course.welcome.p2': 'The beginner\'s course takes about ten minutes. You follow a concrete example, {example}, through the app\'s eight modes: {modes}. In every step you can do the task yourself or let the course do it for you.',
    'course.welcome.p3': 'The screen looks the same in every mode: the modes at the top, the object panel on the left, the workspace in the middle, the properties on the right and the log at the bottom. The course can be minimised and reopened from the help.',
    'course.import.title': 'Import: get data',
    'course.import.p1': 'All data in the app live in datasets: tables with named columns, where each column has a type such as text, integer, number or date. Data can come from files (CSV, Excel, JSON, Parquet, SPSS and more), pasted text, web addresses and open APIs from agencies across the Nordic countries.',
    'course.import.task': 'Go to {mode} and click {button}. This creates the dataset {name}.',
    'course.import.done': 'The dataset has been created: 290 Swedish municipalities with the columns kommunkod (municipality code), kommun (municipality), lanskod (county code), lan (county), ar (year) and folkmangd (population). Its short name is {short}.',
    'course.manage.title': 'Manage: datasets and the workspace',
    'course.manage.p1': 'Every dataset has a name and a short name. The short name, here {short}, has only lower-case letters, digits and underscores and is used in SQL and R. In {mode} you see the source, the size, the columns with types and descriptions, and versions you can go back to.',
    'course.manage.p2': 'Everything is saved automatically in the browser. Back up the workspace now and then with {backup} so that nothing is lost if the browser\'s data are cleared.',
    'course.manage.task': 'Open {mode}, choose the dataset in the object panel and look at its details and columns.',
    'course.manage.done': 'Here you can also change the name and the short name, share datasets as packages and delete them.',
    'course.process.title': 'Process: clean and calculate',
    'course.process.p1': 'In {mode} you see the whole table. Click a column heading to sort and to see the column\'s profile with missing values, unique values and distribution. Correct values directly in the cells or with actions.',
    'course.process.p2': 'Every change becomes a step in the dataset\'s {recipe}. Steps can be undone, replayed on a new version of the data and copied as R or SQL code.',
    'course.process.task': 'Make a column with the population in thousands: {mode} → {actions} → {group} → {op}. Enter the name {column} and the expression {expression}.',
    'course.process.done': 'The column {column} is now last in the table, and the step is in the recipe.',
    'course.sql.title': 'Analyse: query with SQL',
    'course.sql.p1': '{mode} is the mode for code and statistics. In the SQL tab the selected dataset is called {data}, but every dataset can also be reached by its short name, so one query can combine several datasets.',
    'course.sql.task': 'Open {mode} → {tab}, type the query below and click {run}. It sums the population per county.',
    'course.sql.done': 'Stockholm County is the largest with almost 2.5 million inhabitants, followed by Västra Götaland and Skåne. With {save} the result becomes a new dataset.',
    'course.r.title': 'Analyse: calculate with R',
    'course.r.p1': 'The R tab runs R directly in the browser, with packages such as dplyr and ggplot2. {read} reads a dataset as a data frame, and {write} saves a data frame as a new dataset. The first time, R takes a few seconds to start.',
    'course.r.task': 'Open {mode} → {tab}, type the code below and click {run}. It summarises the population and draws a histogram.',
    'course.r.done': 'The median is just over 16,000 inhabitants: half of the municipalities are smaller than that, and the largest, Stockholm, has almost a million. That is why the chart uses a logarithmic scale.',
    'course.viz.title': 'Visualise: make a chart',
    'course.viz.p1': 'Charts are made with the chart builder (Vega-Lite), ready-made D3 templates or R. They all use the app\'s colours and fonts, are redrawn when the data change and can be combined in dashboards with shared filters.',
    'course.viz.task': 'Open {mode} → {new} → {builder}. Choose {type}, set {x} to lan ({y} is already folkmangd) and click {save}.',
    'course.viz.done': 'The chart is saved. Also try the chart type {map} together with the example dataset {boundaries} to show the population on a map.',
    'course.export.title': 'Export: share the result',
    'course.export.p1': 'In {mode} you save data as CSV, Excel, JSON, Parquet, SQLite, SPSS and other formats, charts as PNG, SVG, PDF or PowerPoint, and documents from templates as Word, PDF, HTML or LaTeX, even one document per group in a single run.',
    'course.export.task': 'Open {mode}, choose for example the Excel format and click {run}.',
    'course.export.done': 'The file ends up among the browser\'s downloads. The {charts} and {documents} tabs work the same way for charts and documents.',
    'course.finish.title': 'Done: where to go next',
    'course.finish.p1': 'You have gone through the whole chain: import, manage, process, analyse, visualise and export.',
    'course.finish.p2': 'Carry on with your own data: drop a file in {import}, choose countries and fetch from an open API, write notebooks with text, R and SQL in {analyse}, or make document templates in {export}. Alt+1–6 switches mode and {palette} opens the command palette.',
    'course.finish.p3': 'The course stays available under {help} and in the command palette.',
    'floating.collapse': 'Minimise',
    'floating.expand': 'Show',
