    'families.postgrest.desc': 'Tables and views in PostgreSQL through PostgREST or Supabase. Every table becomes an endpoint with column selection, sorting and filters.',
    'families.postgrest.cors': 'PostgREST and Supabase allow browser calls by default.',
    'families.odata.desc': 'OData v4 services (Dynamics, SharePoint, SAP, statistics services). Entity sets become endpoints with $select, $filter and $orderby; further pages follow @odata.nextLink.',
    'families.odata.cors': 'Depends on the service; the server must allow the browser\'s origin (a page opened from a folder sends the origin "null").',
    'families.graphql.desc': 'Any GraphQL endpoint. You write the query; the first list in the response becomes the table.',
    'families.graphql.cors': 'Depends on the server; most GraphQL servers can enable CORS.',
    'families.couchdb.desc': 'Databases in CouchDB. Every document of a database becomes a row, with the fields as columns.',
    'families.couchdb.cors': 'Enable CORS in CouchDB (Configuration → CORS, or [cors] in local.ini) and add the origin.',
    'families.clickhouse.desc': 'ClickHouse through its HTTP interface. Every table gets an SQL endpoint you can change freely.',
    'families.clickhouse.cors': 'The app sends add_http_cors_header=1, so ClickHouse answers with CORS headers when the user may change that setting.',
    'families.elasticsearch.desc': 'Indices in Elasticsearch or OpenSearch. The hits\' _source becomes columns; at most 10,000 rows per search.',
    'families.elasticsearch.cors': 'Set http.cors.enabled: true and http.cors.allow-origin in elasticsearch.yml (same keys in OpenSearch).',
    'families.sparql.desc': 'SPARQL endpoints such as Wikidata, Europeana or your own triple store. The query\'s variables become columns.',
    'families.sparql.cors': 'Public endpoints such as Wikidata allow browser calls; own servers (Fuseki, GraphDB, Virtuoso) can enable CORS.',
    'families.influxdb.desc': 'InfluxDB v2 through Flux queries. The response (annotated CSV) becomes a table with _time, _value, _field and the tags.',
    'families.influxdb.cors': 'The server must answer with CORS headers; if it does not work from the browser, use the proxy setting or the bridge through ODBC.',
    'families.sheets.desc': 'A Google Sheet published to the web or shared by link. It is read as CSV.',
    'families.sheets.cors': 'The sheet must be published to the web (File → Share → Publish to web) or shared by link; private sheets cannot be read.',
    'families.airtable.desc': 'Tables in an Airtable base through a personal access token. Records become rows with the fields as columns; all pages are fetched.',
    'families.airtable.cors': 'Airtable\'s API allows browser calls.',
