    'geo.hint.measure': 'Area in km², length in km, centroid and extent of every feature.',
    'geo.hint.points': 'Count the selected dataset\'s points per area in another dataset, or give every point the area\'s attributes.',
    'geo.hint.nearest': 'The nearest feature in another dataset for every feature, with the distance in km.',
    'geo.hint.buffer': 'Zones at a chosen distance around every feature.',
    'geo.hint.overlay': 'Intersection or difference between the selected dataset\'s areas and another dataset\'s.',
    'geo.hint.dissolve': 'Merges areas with the same value in a column (or all of them) into one feature.',
    'geo.hint.simplify': 'Simplifies the geometries with a chosen tolerance, for faster maps and smaller files.',
    'geo.about.measure': 'The area is computed on the globe (WGS 84) with holes subtracted; the length applies to lines. The centre is the geometry\'s centroid.',
    'geo.about.points': 'Points inside an area count towards it; points on the border may fall to the neighbour. Lines and areas count through their centroid.',
    'geo.about.nearest': 'The distance is measured between the features\' centroids (great circle), not between their edges.',
    'geo.about.buffer': 'Buffers are computed planar through Turf; for distances up to a few kilometres in the Nordic countries the error is small.',
    'geo.about.overlay': 'The intersection gives one feature per overlapping pair with both sets of attributes; columns with the same name get the prefix b_. The difference removes every overlapping part from the first layer.',
    'geo.about.dissolve': 'The union is computed per group; separate areas become a multipolygon. The result has count and area.',
    'geo.about.simplify': 'Douglas-Peucker with the tolerance converted to degrees (about 111 km per degree).',
