    'geodata.badge.api': 'API',
    'families.wfs.desc': 'OGC Web Feature Service 2.0 (GeoServer, MapServer, Deegree and others). The layers are read from GetCapabilities; each layer becomes an endpoint answering GeoJSON in WGS 84 with an area (bbox), a CQL filter and a choice of columns.',
    'families.wfs.cors': 'The server must allow requests from the browser; most agencies\' GeoServer does.',
    'families.ogcapi.desc': 'OGC API Features (for example Lantmäteriet\'s national geodata platform). The collections are read from /collections; each collection becomes an endpoint with an area (bbox), a time filter and a filter, and further pages are followed through the next link.',
    'families.ogcapi.cors': 'Depends on the service; Lantmäteriet\'s platform allows requests from the browser but requires a key.',
    'families.arcgis.desc': 'ArcGIS REST (FeatureServer or MapServer). The layers are read from the service description, or every service in a directory; each layer becomes an endpoint with a where clause and an area, answering GeoJSON.',
    'families.arcgis.cors': 'ArcGIS Server usually allows requests from the browser.',
